    if args.get("calendar"):
        calfile = args["calendar"]
        if not os.path.isabs(calfile):
            calfile = os.path.join(os.getcwd(), calfile)
    else:
        calfile = os.path.join(datadir, "apts")
    return datadir, confdir, calfile

def ensure_datadir(datadir, confdir):
    for d in [datadir, confdir]:
        try:
            os.makedirs(d, exist_ok=True)
        except PermissionError:
            fatal_create(d)
        except OSError:
            try:
                os.makedirs(d, exist_ok=True)
            except:
                fatal_create(d)
    notes_dir = os.path.join(datadir, "notes")
    hooks_dir = os.path.join(confdir, "hooks")
    for d in [notes_dir, hooks_dir]:
        try:
            os.makedirs(d, exist_ok=True)
        except:
            pass
    for f in [os.path.join(datadir, "apts"), os.path.join(datadir, "todo"), os.path.join(confdir, "conf")]:
        if not os.path.exists(f):
            try:
                open(f, "a").close()
            except:
                pass
    return notes_dir

# Date handling
def parse_input_datefmt(val):
    if val not in ("1","2","3","4"):
        eprint(f"args.c: 852: invalid input date format: {val}\n")
        sys.exit(1)
    return val

def parse_date_str(s, fmt="1", allow_time=True):
    s = s.strip()
    low = s.lower()
    today = datetime.datetime.now().replace(hour=0, minute=0, second=0, microsecond=0)
    if low in ("today","now"):
        return today
    if low == "tomorrow":
        return today + datetime.timedelta(days=1)
    if low == "yesterday":
        return today - datetime.timedelta(days=1)
    weekdays = {"mon":0,"tue":1,"wed":2,"thu":3,"fri":4,"sat":5,"sun":6,
                "monday":0,"tuesday":1,"wednesday":2,"thursday":3,"friday":4,"saturday":5,"sunday":6}
    if low in weekdays:
        target = weekdays[low]
        today_wday = datetime.datetime.now().weekday()
        delta = (target - today_wday) % 7
        if delta == 0:
            delta = 7
        return today + datetime.timedelta(days=delta)
    # handle time part
    time_part = None
    if allow_time and " " in s:
        parts = s.rsplit(" ", 1)
        date_part, maybe_time = parts
        if re.match(r"^\d{1,2}:\d{2}$", maybe_time):
            s = date_part
            time_part = maybe_time
        else:
            # not time, keep as is
            pass
    try:
        if fmt == "1":
            m = re.match(r"^\s*(\d{1,2})/(\d{1,2})/(\d{4})\s*$", s)
            if not m: raise ValueError
            mm, dd, yyyy = int(m.group(1)), int(m.group(2)), int(m.group(3))
            month, day, year = mm, dd, yyyy
        elif fmt == "2":
            m = re.match(r"^\s*(\d{1,2})/(\d{1,2})/(\d{4})\s*$", s)
            if not m: raise ValueError
            dd, mm, yyyy = int(m.group(1)), int(m.group(2)), int(m.group(3))
            month, day, year = mm, dd, yyyy
        elif fmt == "3":
            m = re.match(r"^\s*(\d{4})/(\d{1,2})/(\d{1,2})\s*$", s)
            if not m: raise ValueError
            yyyy, mm, dd = int(m.group(1)), int(m.group(2)), int(m.group(3))
            month, day, year = mm, dd, yyyy
        elif fmt == "4":
            m = re.match(r"^\s*(\d{4})-(\d{1,2})-(\d{1,2})\s*$", s)
            if not m: raise ValueError
            yyyy, mm, dd = int(m.group(1)), int(m.group(2)), int(m.group(3))
            month, day, year = mm, dd, yyyy
        else:
            raise ValueError
        dt = datetime.datetime(year, month, day)
        if time_part:
            hh, mm2 = map(int, time_part.split(":"))
            dt = dt.replace(hour=hh, minute=mm2)
        else:
            dt = dt.replace(hour=0, minute=0, second=0, microsecond=0)
        if year < 1902 or year > 2037:
            raise ValueError
        # validate date is real (datetime already)
        return dt
    except:
        return None

def parse_output_datefmt(fmt):
    if fmt == "":
        eprint(f"args.c: 859: invalid output date format: \n")
        sys.exit(1)
    try:
        datetime.datetime.now().strftime(fmt)
    except:
        eprint(f"args.c: 859: invalid output date format: {fmt}\n")
        sys.exit(1)
    return fmt

