# Helper for loading items
class CalItem:
    def __init__(self, raw, typ, start, end, desc, note_hash=None, note_content=None, recurrence=None, is_todo=False, priority=None, completed=False, raw_hash=None):
        self.raw = raw
        self.typ = typ
        self.start = start
        self.end = end
        self.desc = desc
        self.note_hash = note_hash
        self.note_content = note_content
        self.recurrence = recurrence
        self.is_todo = is_todo
        self.priority = priority
        self.completed = completed
        self.raw_hash = raw_hash

def compute_item_hash(raw):
    return hashlib.sha1(raw.encode()).hexdigest()

def parse_apts_line(line):
    # returns CalItem
    line=line.rstrip("\n")
    if not line:
        return None
    # todo lines start with [
    if line.startswith("["):
        # todo
        m=re.match(r"^\[([^\]]+)\](?:>([0-9a-f]{40}))?\s*(.*)$", line)
        if not m:
            return None
        prio_str=m.group(1)
        note_hash=m.group(2)
        desc=m.group(3)
        # priority parse: could be "-3" or "2" etc
        try:
            # prio_str may be "2" or "-0" or "-3"
            prio = int(prio_str)
            completed=False
            if prio_str.startswith("-"):
                completed=True
                prio = abs(prio)  # but keep? For [-0], prio 0
                # Actually priority for completed includes negative sign; original stores priority with sign for completed.
                # We'll store completed flag and priority as int without sign?
                # For display, completed todos maybe hidden?
            else:
                completed=False
        except:
            return None
        raw=line
        h=compute_item_hash(raw)
        return CalItem(raw, "todo", None, None, desc, note_hash, None, None, True, prio, completed, h)
    # appointment vs event
    if " @ " in line:
        # appointment
        # pattern: start @ time -> end @ time [{recurrence}] [>hash] |desc
        # Use regex
        # Example: "01/01/2000 @ 00:00 -> 01/02/2000 @ 00:00|One day"
        # With recurrence: "01/01/2000 @ 00:00 -> 01/01/2000 @ 01:30 {2D -> 02/01/2000 !01/15/2000 !01/23/2000} |Recurring appointment"
        # With note: "04/04/2020 @ 20:45 -> 04/04/2020 @ 22:15>hash |desc"
        # Determine note hash and description and recurrence
        # Find "|"
        pipe_idx = line.find("|")
        desc=""
        note_hash=None
        recur=None
        if pipe_idx != -1:
            desc = line[pipe_idx+1:]
            prefix = line[:pipe_idx]
        else:
            # might be no pipe? For appointments without desc? but all have |
            prefix=line
            desc=""
        # check for recurrence {...}
        rec_match=re.search(r"\{([^}]*)\}", prefix)
        if rec_match:
            recur = rec_match.group(1).strip()
            # remove recurrence from prefix for parsing times
            prefix_wo = prefix[:rec_match.start()] + prefix[rec_match.end():]
        else:
            prefix_wo=prefix
        # check for >hash in prefix_wo
        m=re.search(r">([0-9a-f]{40})", prefix_wo)
        if m:
            note_hash=m.group(1)
            # remove it
            prefix_wo = prefix_wo.replace(">"+note_hash, "")
        # now prefix_wo should contain times: "MM/DD/YYYY @ HH:MM -> MM/DD/YYYY @ HH:MM"
        m=re.match(r"^\s*(\d{2}/\d{2}/\d{4})\s*@\s*(\d{2}:\d{2})\s*->\s*(\d{2}/\d{2}/\d{4})\s*@\s*(\d{2}:\d{2})\s*$", prefix_wo)
        if not m:
            return None
        s_date, s_time, e_date, e_time = m.groups()
        try:
            start = datetime.datetime.strptime(f"{s_date} {s_time}", "%m/%d/%Y %H:%M")
            end = datetime.datetime.strptime(f"{e_date} {e_time}", "%m/%d/%Y %H:%M")
        except:
            return None
        typ = "recur-apt" if recur else "apt"
        raw=line
        h=compute_item_hash(raw)
        return CalItem(raw, typ, start, end, desc, note_hash, None, recur, False, None, False, h)
    else:
        # event
        # pattern: "MM/DD/YYYY [1] [{recurrence}] [>hash] description"
        # For simple event: "10/03/2013 [1] All day"
        # For recurring: "05/02/2020 [1] {1D -> 05/03/2020} >hash First weekend"
        # Use regex
        # First extract recurrence if present
        recur=None
        rec_match=re.search(r"\{([^}]*)\}", line)
        if rec_match:
            recur=rec_match.group(1).strip()
            prefix = line[:rec_match.start()] + line[rec_match.end():]
        else:
            prefix=line
        # check >hash
        note_hash=None
        m=re.search(r">([0-9a-f]{40})", prefix)
        if m:
            note_hash=m.group(1)
            prefix=prefix.replace(">"+note_hash, "")
        # Now prefix should be "MM/DD/YYYY [1] description" or "MM/DD/YYYY description"? but all events have [1]?
        # Extract date
        m=re.match(r"^\s*(\d{2}/\d{2}/\d{4})\s*(?:\[(\d+)\])?\s*(.*)$", prefix)
        if not m:
            return None
        date_str = m.group(1)
        bracket = m.group(2)
        desc = m.group(3)
        try:
            start = datetime.datetime.strptime(date_str, "%m/%d/%Y")
        except:
            return None
        # For events, end is exclusive? We can treat as start + 1 day if not recurring multi-day? But for query we need to know duration
        # If bracket maybe indicates days? But we'll treat single day event as 1 day
        # For recurring multi-day, recurrence indicates ...
        typ = "recur-event" if recur else "event"
        raw=line
        h=compute_item_hash(raw)
        # For events, start at midnight, end at end of day? But we can set end = start + timedelta(days=1) - 1 sec
        # For display, we don't need exact end time, just date
        end = start + datetime.timedelta(days=1) - datetime.timedelta(seconds=1)
        # If bracket indicates more days? For two days event stored as recurring, we already handle recurrence
        return CalItem(raw, typ, start, end, desc, note_hash, None, recur, False, None, False, h)

def load_items(datadir, calfile, todo_file=None):
    items=[]
    # load apts
    if os.path.exists(calfile):
        for line in open(calfile, encoding="utf-8", errors="ignore"):
            line=line.strip("\n")
            if not line.strip():
                continue
            it=parse_apts_line(line)
            if it:
                # load note content if exists
                if it.note_hash:
                    npath=os.path.join(datadir,"notes", it.note_hash)
                    if os.path.exists(npath):
                        it.note_content=open(npath, encoding="utf-8", errors="ignore").read()
                items.append(it)
            else:
                # syntax error? original would print error: io.c: 543: ... syntax error
                # For now ignore but print to stderr?
                # We could print same as original?
                pass
    # load todo
    if todo_file is None:
        todo_file=os.path.join(datadir,"todo")
    if os.path.exists(todo_file):
        for line in open(todo_file, encoding="utf-8", errors="ignore"):
            line=line.strip("\n")
            if not line.strip():
                continue
            it=parse_apts_line(line)  # same parser handles todos
            if it:
                if it.note_hash:
                    npath=os.path.join(datadir,"notes", it.note_hash)
                    if os.path.exists(npath):
                        it.note_content=open(npath, encoding="utf-8", errors="ignore").read()
                items.append(it)
            else:
                eprint(f"io.c: 543: {todo_file}:{1}: syntax error in item identifier\n")
    return items

def save_items(items, datadir, calfile):
    apts_lines=[]
    todo_lines=[]
    for it in items:
        if it.is_todo:
            todo_lines.append(it.raw)
        else:
            apts_lines.append(it.raw)
    open(calfile,"w", encoding="utf-8").write("\n".join(apts_lines)+("\n" if apts_lines else ""))
    open(os.path.join(datadir,"todo"),"w", encoding="utf-8").write("\n".join(todo_lines)+("\n" if todo_lines else ""))

# Ical handling
def unescape_ical(s):
    # replace escaped
    s=s.replace("\\n","\n")
    s=s.replace("\\N","\n")
    s=s.replace("\\,"," ,") # placeholder?
    # Actually original replaces "\," with ","
    # We'll do correctly
    # But need order: \\ first?
    # Use placeholder
    s=s.replace("\\\\","\\")
    s=s.replace("\\,"," ,")
    # Correct: after, replace ","
    # Let's implement properly: iterate
    # Simpler: replace "\\" with placeholder, then "\n" etc
    return s

def escape_ical(s):
    s=s.replace("\\","\\\\")
    s=s.replace("\n","\\n")
    s=s.replace(",","\\,")
    s=s.replace(";","\\;")
    return s

def parse_ical_duration(dur):
    # P1DT9H17M0S, PT1H30M0S, P1DT0H0M0S etc
    # Return timedelta
    m=re.match(r"^P(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?)?$", dur)
    if not m:
        # also handle P1DT9H17M etc? already
        # Also P1W ?
        m2=re.match(r"^P(\d+)W$", dur)
        if m2:
            weeks=int(m2.group(1))
            return datetime.timedelta(weeks=weeks)
        return None
    days=int(m.group(1)) if m.group(1) else 0
    hours=int(m.group(2)) if m.group(2) else 0
    minutes=int(m.group(3)) if m.group(3) else 0
    seconds=int(m.group(4)) if m.group(4) else 0
    return datetime.timedelta(days=days, hours=hours, minutes=minutes, seconds=seconds)

def format_ical_duration(td):
    # format as P0DT... ??? Original uses P...D... etc with days
    days=td.days
    secs=td.seconds
    hours=secs//3600
    secs%=3600
    minutes=secs//60
    secs%=60
    if days>0:
        return f"P{days}DT{hours}H{minutes}M{secs}S"
    else:
        return f"P0DT{hours}H{minutes}M{secs}S"

def do_import(import_file, datadir, confdir, calfile, args):
    # read file
    if not os.path.exists(import_file):
        eprint(f"io.c: 1278: FATAL ERROR: the input file cannot be accessed, Aborting...\n")
        sys.exit(1)
    try:
        content=open(import_file, encoding="utf-8", errors="ignore").read()
    except:
        eprint(f"io.c: 1278: FATAL ERROR: the input file cannot be accessed, Aborting...\n")
        sys.exit(1)
    lines=content.splitlines()
    lines_read=len(lines)
    # unfold
    unfolded=[]
    for l in lines:
        if l.startswith(" ") or l.startswith("\t"):
            if unfolded:
                unfolded[-1]+=l[1:]
            else:
                unfolded.append(l[1:])
        else:
            unfolded.append(l)
    # parse
    apps=0
    events=0
    todos=0
    skipped=0
    new_items=[]
    notes_to_write=[]
