                        valid_wds.add(wd)
                    except:
                        pass
            if candidate_date.weekday() not in valid_wds:
                return False
        else:
            # default: only dtstart weekday
            if candidate_date.weekday() != dtstart.weekday():
                return False
    elif freq=="MONTHLY":
        # months diff
        months=(candidate_date.year - dtstart.year)*12 + (candidate_date.month - dtstart.month)
        if months % interval !=0:
