def parse_date_str(s, fmt="1", allow_time=True):
    s = s.strip()
    low = s.lower()
    today = datetime.datetime.now().replace(hour=0, minute=0, second=0, microsecond=0)
    if low in ("today","now"):
        return today
    if low == "tomorrow":
        return today + datetime.timedelta(days=1)
    if low == "yesterday":
        return today - datetime.timedelta(days=1)
    weekdays = {"mon":0,"tue":1,"wed":2,"thu":3,"fri":4,"sat":5,"sun":6,
                "monday":0,"tuesday":1,"wednesday":2,"thursday":3,"friday":4,"saturday":5,"sunday":6}
    if low in weekdays:
        target = weekdays[low]
        today_wday = datetime.datetime.now().weekday()
        delta = (target - today_wday) % 7
        if delta == 0:
            delta = 7
        return today + datetime.timedelta(days=delta)
    time_part = None
    if allow_time and " " in s:
        parts = s.rsplit(" ", 1)
        date_part, maybe_time = parts
        if re.match(r"^\d{1,2}:\d{2}$", maybe_time):
            s = date_part
            time_part = maybe_time
    try:
        if fmt == "1":
            m = re.match(r"^\s*(\d{1,2})/(\d{1,2})/(\d{4})\s*$", s)
            if not m: raise ValueError
            mm, dd, yyyy = int(m.group(1)), int(m.group(2)), int(m.group(3))
            month, day, year = mm, dd, yyyy
        elif fmt == "2":
            m = re.match(r"^\s*(\d{1,2})/(\d{1,2})/(\d{4})\s*$", s)
            if not m: raise ValueError
            dd, mm, yyyy = int(m.group(1)), int(m.group(2)), int(m.group(3))
            month, day, year = mm, dd, yyyy
        elif fmt == "3":
            m = re.match(r"^\s*(\d{4})/(\d{1,2})/(\d{1,2})\s*$", s)
            if not m: raise ValueError
            yyyy, mm, dd = int(m.group(1)), int(m.group(2)), int(m.group(3))
            month, day, year = mm, dd, yyyy
        elif fmt == "4":
            m = re.match(r"^\s*(\d{4})-(\d{1,2})-(\d{1,2})\s*$", s)
            if not m: raise ValueError
            yyyy, mm, dd = int(m.group(1)), int(m.group(2)), int(m.group(3))
            month, day, year = mm, dd, yyyy
        else:
            raise ValueError
        dt = datetime.datetime(year, month, day)
        if time_part:
            hh, mm2 = map(int, time_part.split(":"))
            dt = dt.replace(hour=hh, minute=mm2)
        else:
            dt = dt.replace(hour=0, minute=0, second=0, microsecond=0)
        if year < 1902 or year > 2037:
            raise ValueError
        return dt
    except:
        return None

def parse_output_datefmt(fmt):
    if fmt == "":
        eprint(f"args.c: 859: invalid output date format: \n")
        sys.exit(1)
    try:
        datetime.datetime.now().strftime(fmt)
    except:
        eprint(f"args.c: 859: invalid output date format: {fmt}\n")
        sys.exit(1)
    return fmt

class CalItem:
    def __init__(self, raw, typ, start, end, desc, note_hash=None, note_content=None, recurrence=None, is_todo=False, priority=None, completed=False, raw_hash=None, exdates=None, rrule=None):
        self.raw = raw
        self.typ = typ
        self.start = start
        self.end = end
        self.desc = desc
        self.note_hash = note_hash
        self.note_content = note_content
        self.recurrence = recurrence
        self.is_todo = is_todo
        self.priority = priority
        self.completed = completed
        self.raw_hash = raw_hash
        self.exdates = exdates or []
        self.rrule = rrule  # dict

def compute_item_hash(raw):
    return hashlib.sha1(raw.encode()).hexdigest()

def parse_apts_line(line):
    line=line.rstrip("\n")
    if not line.strip():
        return None
    if line.startswith("["):
        m=re.match(r"^\[([^\]]+)\](?:>([0-9a-f]{40}))?\s*(.*)$", line)
        if not m:
            return None
        prio_str=m.group(1)
        note_hash=m.group(2)
        desc=m.group(3)
        try:
            prio = int(prio_str)
            completed=False
            if prio_str.startswith("-"):
                completed=True
                prio = abs(prio)
        except:
            return None
        raw=line
        h=compute_item_hash(raw)
        return CalItem(raw, "todo", None, None, desc, note_hash, None, None, True, prio, completed, h)
    if " @ " in line:
        pipe_idx = line.find("|")
        desc=""
        note_hash=None
        recur=None
        exdates=[]
        rrule=None
        if pipe_idx != -1:
            desc = line[pipe_idx+1:]
            prefix = line[:pipe_idx]
        else:
            prefix=line
            desc=""
        rec_match=re.search(r"\{([^}]*)\}", prefix)
        if rec_match:
            recur = rec_match.group(1).strip()
            prefix_wo = prefix[:rec_match.start()] + prefix[rec_match.end():]
        else:
            prefix_wo=prefix
        # parse recurrence for exdates and rrule
        if recur:
            # recur may contain !exdates and tokens
            parts=recur.split()
            tokens=[]
            for p in parts:
                if p.startswith("!"):
                    exdates.append(p[1:])
                else:
                    tokens.append(p)
            # first token is like "2D" or "1M" or "1Y" etc, optionally with -> date
            # We'll store recur tokens for later
            rrule = {"raw":recur, "tokens":tokens, "exdates":exdates}
        m=re.search(r">([0-9a-f]{40})", prefix_wo)
        if m:
            note_hash=m.group(1)
            prefix_wo = prefix_wo.replace(">"+note_hash, "")
        m=re.match(r"^\s*(\d{2}/\d{2}/\d{4})\s*@\s*(\d{2}:\d{2})\s*->\s*(\d{2}/\d{2}/\d{4})\s*@\s*(\d{2}:\d{2})\s*$", prefix_wo)
        if not m:
            return None
        s_date, s_time, e_date, e_time = m.groups()
        try:
            start = datetime.datetime.strptime(f"{s_date} {s_time}", "%m/%d/%Y %H:%M")
            end = datetime.datetime.strptime(f"{e_date} {e_time}", "%m/%d/%Y %H:%M")
        except:
            return None
        typ = "recur-apt" if recur else "apt"
        raw=line
        h=compute_item_hash(raw)
        return CalItem(raw, typ, start, end, desc, note_hash, None, recur, False, None, False, h, exdates, rrule)
    else:
        recur=None
        exdates=[]
        rrule=None
        rec_match=re.search(r"\{([^}]*)\}", line)
        if rec_match:
            recur=rec_match.group(1).strip()
            prefix = line[:rec_match.start()] + line[rec_match.end():]
        else:
            prefix=line
        note_hash=None
        m=re.search(r">([0-9a-f]{40})", prefix)
        if m:
            note_hash=m.group(1)
            prefix=prefix.replace(">"+note_hash, "")
        if recur:
            parts=recur.split()
            tokens=[]
            for p in parts:
                if p.startswith("!"):
                    exdates.append(p[1:])
                else:
                    tokens.append(p)
            rrule={"raw":recur,"tokens":tokens,"exdates":exdates}
        m=re.match(r"^\s*(\d{2}/\d{2}/\d{4})\s*(?:\[(\d+)\])?\s*(.*)$", prefix)
        if not m:
            return None
        date_str = m.group(1)
        bracket = m.group(2)
        desc = m.group(3)
        try:
            start = datetime.datetime.strptime(date_str, "%m/%d/%Y")
        except:
            return None
        end = start + datetime.timedelta(days=1) - datetime.timedelta(seconds=1)
        typ = "recur-event" if recur else "event"
        raw=line
        h=compute_item_hash(raw)
        return CalItem(raw, typ, start, end, desc, note_hash, None, recur, False, None, False, h, exdates, rrule)

def load_items(datadir, calfile, todo_file=None):
    items=[]
    if os.path.exists(calfile):
        for line in open(calfile, encoding="utf-8", errors="ignore"):
            line=line.strip("\n")
            if not line.strip():
                continue
            it=parse_apts_line(line)
            if it:
                if it.note_hash:
                    npath=os.path.join(datadir,"notes", it.note_hash)
                    if os.path.exists(npath):
                        it.note_content=open(npath, encoding="utf-8", errors="ignore").read()
                items.append(it)
    if todo_file is None:
        todo_file=os.path.join(datadir,"todo")
    if os.path.exists(todo_file):
        for line in open(todo_file, encoding="utf-8", errors="ignore"):
            line=line.strip("\n")
            if not line.strip():
                continue
            it=parse_apts_line(line)
            if it:
                if it.note_hash:
                    npath=os.path.join(datadir,"notes", it.note_hash)
                    if os.path.exists(npath):
                        it.note_content=open(npath, encoding="utf-8", errors="ignore").read()
                items.append(it)
            else:
                eprint(f"io.c: 543: {todo_file}:{1}: syntax error in item identifier\n")
    return items

def save_items(items, datadir, calfile):
    apts_lines=[]
    todo_lines=[]
    for it in items:
        if it.is_todo:
            todo_lines.append(it.raw)
        else:
            apts_lines.append(it.raw)
    open(calfile,"w", encoding="utf-8").write("\n".join(apts_lines)+("\n" if apts_lines else ""))
    open(os.path.join(datadir,"todo"),"w", encoding="utf-8").write("\n".join(todo_lines)+("\n" if todo_lines else ""))

def parse_ical_duration(dur):
    m=re.match(r"^P(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?)?$", dur)
    if not m:
        m2=re.match(r"^P(\d+)W$", dur)
        if m2:
            weeks=int(m2.group(1))
            return datetime.timedelta(weeks=weeks)
        return None
    days=int(m.group(1)) if m.group(1) else 0
    hours=int(m.group(2)) if m.group(2) else 0
    minutes=int(m.group(3)) if m.group(3) else 0
    seconds=int(m.group(4)) if m.group(4) else 0
    return datetime.timedelta(days=days, hours=hours, minutes=minutes, seconds=seconds)

def format_ical_duration(td):
    days=td.days
    secs=td.seconds
    hours=secs//3600
    secs%=3600
    minutes=secs//60
    secs%=60
    if days>0:
        return f"P{days}DT{hours}H{minutes}M{secs}S"
    else:
        return f"P0DT{hours}H{minutes}M{secs}S"

WEEKDAY_MAP = {"MO":0, "TU":1, "WE":2, "TH":3, "FR":4, "SA":5, "SU":6}
WEEKDAY_REV = {0:"MO",1:"TU",2:"WE",3:"TH",4:"FR",5:"SA",6:"SU"}
# For calcurse w numbers, MO=1,...
WEEKDAY_CALCURSE = {"MO":1,"TU":2,"WE":3,"TH":4,"FR":5,"SA":6,"SU":7}

def parse_rrule_str(rrule_str):
    parts=dict(p.split("=") for p in rrule_str.split(";") if "=" in p)
    return parts

def parse_recurrence_spec(spec, dtstart):
    # spec like "2D -> 02/01/2000 !01/15/2000 w2 m11 d2 ..."
    # We need to extract freq, interval, until, and BY* tokens
    # This is for apts file recurrence; we can convert to dict similar to RRULE dict
    tokens=spec.split()
    if not tokens:
        return None
    first=tokens[0]
    # first may be like "2D" or "4Y" or "1M" or "1D" etc, optionally with -> ?
    # But after split, "->" is separate token?
    # Example "1D -> 05/03/2020" -> tokens ["1D", "->", "05/03/2020"]
    # So need to handle
    freq_letter=None
    interval=1
    until=None
    byday=[]
    bymonth=[]
    bymonthday=[]
    exdates=[]
    i=0
    # first token interval+freq
    m=re.match(r"^(\d+)([DWMY])$", tokens[0])
    if m:
        interval=int(m.group(1))
        freq_letter=m.group(2)
        i=1
        if i < len(tokens) and tokens[i]=="->":
            i+=1
            if i < len(tokens):
                try:
                    until=datetime.datetime.strptime(tokens[i], "%m/%d/%Y")
                    i+=1
                except:
                    pass
    # remaining tokens: d*, w*, m*, !*
    for tok in tokens[i:]:
        if tok.startswith("!"):
            exdates.append(tok[1:])
        elif tok.startswith("d"):
            try:
                bymonthday.append(int(tok[1:]))
            except:
                pass
        elif tok.startswith("w"):
            try:
                # w may be like "2" or "-7" or "141" etc for prefix cases
                # we will decode w values to BYDAY entries
                # For simple w without prefix, it's weekday number 0-6 or 1-7
                # For prefix cases, need to decode
                val=tok[1:]
                # We'll store raw w value string for matching
                byday.append(val)
            except:
                pass
        elif tok.startswith("m"):
            try:
                bymonth.append(int(tok[1:]))
            except:
                pass
    # Map freq_letter to FREQ string
    freq_map={"D":"DAILY","W":"WEEKLY","M":"MONTHLY","Y":"YEARLY"}
    freq=freq_map.get(freq_letter,"DAILY")
    return {"FREQ":freq, "INTERVAL":interval, "UNTIL":until, "BYDAY":byday, "BYMONTH":bymonth, "BYMONTHDAY":bymonthday, "EXDATE":exdates, "WKST":"MO"}

def rrule_matches_date(candidate_date, dtstart, rrule):
    # candidate_date is date (midnight)
    # dtstart is datetime
    # rrule dict with FREQ, INTERVAL, UNTIL, BY*, WKST, COUNT etc
    # This is for checking if candidate_date is an occurrence (date part)
    # For appointments, times are same as dtstart time; candidate_date's time is dtstart's time?
    # We'll compare dates only for simplicity, but for appointments the time matters but date suffices for query day.
    if candidate_date < dtstart.replace(hour=0, minute=0, second=0, microsecond=0):
        return False
    if rrule.get("UNTIL"):
        until=rrule["UNTIL"]
        if candidate_date > until.replace(hour=0, minute=0, second=0, microsecond=0):
            return False
    # COUNT handling: need to count occurrences up to candidate
    # For COUNT, we need to know occurrence index; if index > COUNT, false
    freq=rrule["FREQ"]
    interval=rrule["INTERVAL"]
    # interval alignment
    if freq=="DAILY":
        delta=(candidate_date - dtstart.replace(hour=0, minute=0, second=0, microsecond=0)).days
        if delta % interval !=0:
            return False
    elif freq=="WEEKLY":
        # week diff
        # Determine week start for dtstart and candidate based on WKST
        wkst=rrule.get("WKST","MO")
        # Map WKST to weekday number (MO=0)
        wkst_num=WEEKDAY_MAP.get(wkst,0)
        # Find week start for a date: go back to wkst weekday
        def week_start(d):
            # d is datetime
            wd=d.weekday()
            # wkst_num is 0 for MO etc
            diff=(wd - wkst_num) % 7
            return d - datetime.timedelta(days=diff)
        dt_ws=week_start(dtstart.replace(hour=0, minute=0, second=0, microsecond=0))
        cand_ws=week_start(candidate_date)
        delta_days=(cand_ws - dt_ws).days
        weeks=delta_days//7
        if weeks % interval !=0:
            return False
        # Also need BYDAY check: if BYDAY present, candidate weekday must be in list
        # For WEEKLY without BYDAY, default is dtstart weekday
        byday=rrule.get("BYDAY",[])
        if byday:
            # byday may contain w values like "2" etc; convert to weekday numbers
            valid_wds=set()
            for w in byday:
                # w is string like "2" or "0" or "-7" etc for simple?
                # For our rrule from apts spec, BYDAY values are w numbers strings without prefix meaning weekday 1-7,
                # For original RRULE, BYDAY values are like "MO","TU" etc
                # We need to handle both
                if w in WEEKDAY_MAP:
                    valid_wds.add(WEEKDAY_MAP[w])
                else:
                    try:
                        # try numeric w: e.g., "2" -> TU -> weekday 1 (since 2 maps to TU)
                        # But numeric w like "2" corresponds to TU which is 1
                        # So we can map numeric w via calcurse weekday mapping: 1->MO (0), 2->TU (1), etc 7->SU (6), 0->SU (6)
                        num=int(w)
                        # handle prefix cases like "141" etc: those are N*7+weekday, we need to extract weekday
                        # For prefix cases, num encodes N*7+weekday, weekday = num %7 (with special)
                        # But for matching, we care only weekday, not prefix? For WEEKLY, prefix not used? Actually WEEKLY BYDAY with prefix maybe not used; but for YEARLY etc prefix matters.
                        # For WEEKLY, we can just take weekday = (num-1)%7 ? Let's simplify
                        if num>=0:
                            # For 0, SU
                            if num==0:
                                wd=6
                            else:
                                wd=(num-1)%7
                                # But for 2, (2-1)%7=1 => TU correct
                                # For 4, (4-1)%7=3 => TH correct
                                # For 12, (12-1)%7=4 => FR correct but 12 encodes 1FR (should be FR)
                                # So this mapping works for prefix encoded w's as well for weekly?
                                pass
                        else:
                            # negative like -7 => SU
                            wd=abs(num)-1
                            if wd==7:
                                wd=6
                            else:
                                wd=wd%7
                        valid_wds.add(wd)
                    except:
                        pass
            if candidate_date.weekday() not in valid_wds:
                return False
        else:
            # default: only dtstart weekday
            if candidate_date.weekday() != dtstart.weekday():
                return False
    elif freq=="MONTHLY":
        # months diff
        months=(candidate_date.year - dtstart.year)*12 + (candidate_date.month - dtstart.month)
        if months % interval !=0:
            return False
        # BYMONTH check: if BYMONTH present, candidate month must be in list
