def fatal_create(p):
    out(f"FATAL ERROR: could not create {p}: Permission denied\n")
    sys.exit(1)

def resolve_dirs(args):
    home=os.path.expanduser("~")
    xdg_data=os.environ.get("XDG_DATA_HOME", os.path.join(home,".local","share"))
    xdg_config=os.environ.get("XDG_CONFIG_HOME", os.path.join(home,".config"))
    both=os.path.join(home,".calcurse")
    if os.path.isdir(both):
        datadir=both
        confdir=both
    else:
        datadir=os.path.join(xdg_data,"calcurse")
        confdir=os.path.join(xdg_config,"calcurse")
    if args.get("datadir"):
        datadir=args["datadir"]
    if args.get("confdir"):
        confdir=args["confdir"]
    calfile=args.get("calendar")
    if calfile:
        if not os.path.isabs(calfile):
            calfile=os.path.join(os.getcwd(), calfile)
    else:
        calfile=os.path.join(datadir,"apts")
    return datadir,confdir,calfile

def ensure_dirs(datadir,confdir):
    for d in [datadir,confdir]:
        try:
            os.makedirs(d,exist_ok=True)
        except:
            fatal_create(d)
    for d in [os.path.join(datadir,"notes"), os.path.join(confdir,"hooks")]:
        try:
            os.makedirs(d,exist_ok=True)
        except: pass
    for f in [os.path.join(datadir,"apts"), os.path.join(datadir,"todo"), os.path.join(confdir,"conf")]:
        if not os.path.exists(f):
            try:
                open(f,"a").close()
            except: pass

def parse_input_datefmt(v):
    if v not in ("1","2","3","4"):
        eprint(f"args.c: 852: invalid input date format: {v}\n")
        sys.exit(1)
    return v
def parse_output_datefmt(v):
    if v=="":
        eprint(f"args.c: 859: invalid output date format: \n")
        sys.exit(1)
    try:
        datetime.datetime.now().strftime(v)
    except:
        eprint(f"args.c: 859: invalid output date format: {v}\n")
        sys.exit(1)
    return v

def parse_date_str(s, fmt="1", allow_time=True):
    s=s.strip()
    low=s.lower()
    today=datetime.datetime.now().replace(hour=0,minute=0,second=0,microsecond=0)
    if low in ("today","now"):
        return today
    if low=="tomorrow":
        return today+datetime.timedelta(days=1)
    if low=="yesterday":
        return today-datetime.timedelta(days=1)
    wdmap={"mon":0,"tue":1,"wed":2,"thu":3,"fri":4,"sat":5,"sun":6,"monday":0,"tuesday":1,"wednesday":2,"thursday":3,"friday":4,"saturday":5,"sunday":6}
    if low in wdmap:
        target=wdmap[low]
        cur=datetime.datetime.now().weekday()
        delta=(target-cur)%7
        if delta==0:
            delta=7
        return today+datetime.timedelta(days=delta)
    time_part=None
    if allow_time and " " in s:
        a,b=s.rsplit(" ",1)
        if re.match(r"^\d{1,2}:\d{2}$", b):
            s=a
            time_part=b
    try:
        if fmt=="1":
            m=re.match(r"^\s*(\d{1,2})/(\d{1,2})/(\d{4})\s*$", s)
            if not m: raise ValueError
            mm,dd,yyyy=int(m.group(1)),int(m.group(2)),int(m.group(3))
            month,day,year=mm,dd,yyyy
        elif fmt=="2":
            m=re.match(r"^\s*(\d{1,2})/(\d{1,2})/(\d{4})\s*$", s)
            if not m: raise ValueError
            dd,mm,yyyy=int(m.group(1)),int(m.group(2)),int(m.group(3))
            month,day,year=mm,dd,yyyy
        elif fmt=="3":
            m=re.match(r"^\s*(\d{4})/(\d{1,2})/(\d{1,2})\s*$", s)
            if not m: raise ValueError
            yyyy,mm,dd=int(m.group(1)),int(m.group(2)),int(m.group(3))
            month,day,year=mm,dd,yyyy
        elif fmt=="4":
            m=re.match(r"^\s*(\d{4})-(\d{1,2})-(\d{1,2})\s*$", s)
            if not m: raise ValueError
            yyyy,mm,dd=int(m.group(1)),int(m.group(2)),int(m.group(3))
            month,day,year=mm,dd,yyyy
        else:
            raise ValueError
        dt=datetime.datetime(year,month,day)
        if time_part:
            hh,mm2=map(int,time_part.split(":"))
            dt=dt.replace(hour=hh,minute=mm2)
        else:
            dt=dt.replace(hour=0,minute=0,second=0,microsecond=0)
        if year<1902 or year>2037:
            raise ValueError
        return dt
    except:
        return None

# Minimal item handling
def compute_hash(s):
    return hashlib.sha1(s.encode()).hexdigest()

def load_items(datadir, calfile):
    items=[]
    todo_file=os.path.join(datadir,"todo")
    # apts
    if os.path.exists(calfile):
        for line in open(calfile,encoding="utf-8",errors="ignore"):
            line=line.rstrip("\n")
            if not line.strip(): continue
            # create minimal dict
            typ="apt"
            if line.startswith("["):
                typ="todo"
                # todo
                m=re.match(r"^\[([^\]]+)\](?:>([0-9a-f]{40}))?\s*(.*)$", line)
                if m:
                    prio=m.group(1)
                    note=m.group(2)
                    desc=m.group(3)
                    items.append({"raw":line,"type":typ,"prio":prio,"note":note,"desc":desc,"is_todo":True})
                continue
            if " @ " in line:
                # apt
                # check recur
                is_recur="{" in line
                typ="recur-apt" if is_recur else "apt"
                # extract desc after |
                pipe=line.find("|")
                desc=line[pipe+1:] if pipe!=-1 else ""
                # start/end
                # we can parse start date
                m=re.search(r"(\d{2}/\d{2}/\d{4})\s*@\s*(\d{2}:\d{2})", line)
                start=None
                end=None
                if m:
                    try:
                        sd, st = m.groups()
                        start=datetime.datetime.strptime(f"{sd} {st}", "%m/%d/%Y %H:%M")
                    except: pass
                # try second
                m2=re.search(r"->\s*(\d{2}/\d{2}/\d{4})\s*@\s*(\d{2}:\d{2})", line)
                if m2:
                    try:
                        ed, et=m2.groups()
                        end=datetime.datetime.strptime(f"{ed} {et}", "%m/%d/%Y %H:%M")
                    except: pass
                # note hash
                mh=re.search(r">([0-9a-f]{40})", line)
                noteh=mh.group(1) if mh else None
                note_content=None
                if noteh:
                    np=os.path.join(datadir,"notes",noteh)
                    if os.path.exists(np):
                        note_content=open(np,encoding="utf-8",errors="ignore").read()
                items.append({"raw":line,"type":typ,"desc":desc,"start":start,"end":end,"note":noteh,"note_content":note_content,"is_todo":False})
            else:
                is_recur="{" in line
                typ="recur-event" if is_recur else "event"
                m=re.match(r"^\s*(\d{2}/\d{2}/\d{4})\s*(?:\[(\d+)\])?\s*(.*)$", line)
                # need to extract desc after removing recurrence and note
                # For event, desc is after date and maybe note
                # We'll extract via removing recurrence and note
                tmp=line
                rec_match=re.search(r"\{([^}]*)\}", tmp)
                rec=None
                if rec_match:
                    rec=rec_match.group(1)
                    tmp=tmp[:rec_match.start()]+tmp[rec_match.end():]
                mh=re.search(r">([0-9a-f]{40})", tmp)
                noteh=mh.group(1) if mh else None
                if noteh:
                    tmp=tmp.replace(">"+noteh,"")
                # now tmp is "MM/DD/YYYY [1] desc" or similar
                m2=re.match(r"^\s*\d{2}/\d{2}/\d{4}\s*(?:\[\d+\])?\s*(.*)$", tmp)
                desc=m2.group(1) if m2 else ""
                # event start date
                m3=re.match(r"^\s*(\d{2}/\d{2}/\d{4})", tmp)
                start=None
                if m3:
                    try:
                        start=datetime.datetime.strptime(m3.group(1), "%m/%d/%Y")
                    except: pass
                note_content=None
                if noteh:
                    np=os.path.join(datadir,"notes",noteh)
                    if os.path.exists(np):
                        note_content=open(np,encoding="utf-8",errors="ignore").read()
                items.append({"raw":line,"type":typ,"desc":desc,"start":start,"end":None,"note":noteh,"note_content":note_content,"is_todo":False,"recurrence":rec})
    # todo file
    if os.path.exists(todo_file):
        for line in open(todo_file,encoding="utf-8",errors="ignore"):
            line=line.rstrip("\n")
            if not line.strip(): continue
            m=re.match(r"^\[([^\]]+)\](?:>([0-9a-f]{40}))?\s*(.*)$", line)
            if m:
                prio=m.group(1)
                note=m.group(2)
                desc=m.group(3)
                items.append({"raw":line,"type":"todo","prio":prio,"note":note,"desc":desc,"is_todo":True})
            else:
                eprint(f"io.c: 543: {todo_file}:1: syntax error in item identifier\n")
    return items

def apply_format(item, fmt, datadir):
    # handle %(raw), %(hash), %m, %p, %S, %E, %s, %e, %d, %r, %n, %N
    # For todo, %p = priority, %m=desc
    # For apt, %m=desc, %n note hash, %N note content, %S start time hh:mm, %E end time, %s start epoch, %e end epoch, %d duration seconds, %r remaining
    # extended: %(raw), %(hash), %(duration[:format]), %(remaining[:format]), %(start[:format]), %(end[:format])
    # For duration extended, format may be "%d %H:%M" etc with flags - and E
    raw=item.get("raw","")
    h=compute_hash(raw)
    # helper to get start/end
    def fmt_time(dt, fmt_str):
        if fmt_str=="epoch":
            return str(int(dt.timestamp()))
        if fmt_str=="default":
            return dt.strftime("%H:%M")
        try:
            return dt.strftime(fmt_str)
        except:
            return dt.strftime("%H:%M")
    # process extended first
    def repl_ext(m):
        inner=m.group(1)
        if inner=="raw":
            return raw
        if inner=="hash":
            return h
        if inner.startswith("duration"):
            # %(duration:fmt) or %(duration)
            if ":" in inner:
                _, f = inner.split(":",1)
                # f may be like "%d %H:%M"
                # Need to compute duration
                if item.get("start") and item.get("end"):
                    td=item["end"]-item["start"]
                    total=int(td.total_seconds())
                    # for extended, we support %d %H %M %S with flags
                    # We'll compute days, hours, minutes, seconds
                    # total seconds -> days = total//86400, rem, hours clock etc
                    # But need to handle %Ed etc for extended hours beyond 24?
                    # For simplicity, compute straightforward
                    days=total//86400
                    rem=total%86400
                    hours=rem//3600
                    rem%=3600
                    minutes=rem//60
                    secs=rem%60
                    # For %EH etc, hours is total hours, etc?
                    # We'll handle flags
                    # Replace in f string
                    res=""
                    i=0
                    while i < len(f):
                        if f[i]=="%":
                            i+=1
                            flag_minus=False
                            flag_E=False
                            if i < len(f) and f[i]=="-":
                                flag_minus=True
                                i+=1
                            if i < len(f) and f[i]=="E":
                                flag_E=True
                                i+=1
                            if i < len(f):
                                ch=f[i]
                                i+=1
                                val=""
                                if ch=="d":
                                    val=str(days)
                                    if not flag_minus:
                                        val=val.zfill(2)
                                elif ch=="H":
                                    if flag_E:
                                        # total hours
                                        th=total//3600
                                        val=str(th)
                                    else:
                                        val=str(hours)
                                    if not flag_minus:
                                        val=val.zfill(2)
                                elif ch=="M":
                                    if flag_E:
                                        tm=total//60
                                        val=str(tm)
                                    else:
                                        val=str(minutes)
                                    if not flag_minus:
                                        val=val.zfill(2)
                                elif ch=="S":
                                    if flag_E:
                                        val=str(total)
                                    else:
                                        val=str(secs)
                                    if not flag_minus:
                                        val=val.zfill(2)
                                else:
                                    val="%"+ch
                                res+=val
                            else:
                                res+="%"
                        else:
                            res+=f[i]
                            i+=1
                    return res
                else:
                    return "0"
            else:
                # no format, return seconds
                if item.get("start") and item.get("end"):
                    td=item["end"]-item["start"]
                    return str(int(td.total_seconds()))
                return "0"
        if inner.startswith("remaining"):
            # similar to duration but remaining time = start - now ?
            if ":" in inner:
                _, f = inner.split(":",1)
                # compute remaining = start - now
                if item.get("start"):
                    now=datetime.datetime.now()
                    td=item["start"]-now
                    total=int(td.total_seconds())
                    if total<0:
                        total=0
                    days=total//86400
                    rem=total%86400
                    hours=rem//3600
                    rem%=3600
                    minutes=rem//60
                    secs=rem%60
                    res=""
                    i=0
                    while i < len(f):
                        if f[i]=="%":
                            i+=1
                            flag_minus=False
                            flag_E=False
                            if i < len(f) and f[i]=="-":
                                flag_minus=True
                                i+=1
                            if i < len(f) and f[i]=="E":
                                flag_E=True
                                i+=1
                            if i < len(f):
                                ch=f[i]
                                i+=1
                                val=""
                                if ch=="d":
                                    val=str(days)
                                    if not flag_minus: val=val.zfill(2)
                                elif ch=="H":
                                    if flag_E:
                                        th=total//3600
                                        val=str(th)
                                    else:
                                        val=str(hours)
                                    if not flag_minus: val=val.zfill(2)
                                elif ch=="M":
                                    if flag_E:
                                        tm=total//60
                                        val=str(tm)
                                    else:
                                        val=str(minutes)
                                    if not flag_minus: val=val.zfill(2)
                                elif ch=="S":
                                    if flag_E:
                                        val=str(total)
                                    else:
                                        val=str(secs)
                                    if not flag_minus: val=val.zfill(2)
                                else:
                                    val="%"+ch
                                res+=val
                        else:
                            res+=f[i]
                            i+=1
                    return res
                return "0"
            else:
                if item.get("start"):
                    now=datetime.datetime.now()
                    td=item["start"]-now
                    return str(int(td.total_seconds()))
                return "0"
        if inner.startswith("start"):
            if ":" in inner:
                _, f = inner.split(":",1)
                if item.get("start"):
                    return fmt_time(item["start"], f)
                return ""
            else:
                if item.get("start"):
                    return str(int(item["start"].timestamp()))
                return "0"
        if inner.startswith("end"):
            if ":" in inner:
                _, f = inner.split(":",1)
                if item.get("end"):
                    return fmt_time(item["end"], f)
                return ""
            else:
                if item.get("end"):
                    return str(int(item["end"].timestamp()))
                return "0"
        return m.group(0)
    # handle extended %(...)
    fmt2=re.sub(r"%\(([^)]+)\)", repl_ext, fmt)
    # handle short
    res=""
    i=0
    while i < len(fmt2):
        if fmt2[i]=="%" and i+1 < len(fmt2):
            ch=fmt2[i+1]
            if ch=="%":
                res+="%"; i+=2; continue
            elif ch=="m":
                res+=item.get("desc","") or ""
                i+=2
            elif ch=="p":
                # for todo
                prio=item.get("prio","")
                # prio may be like "2" or "-0"
                # For completed, need to show? Original shows priority number for uncompleted, and for completed? But -t0 shows completed todos. For format, %p for completed? Original maybe shows priority with sign? In todo file, completed has "-0" or "-3", but display %p maybe shows "0" or priority?
                # We'll just output prio without sign? But for completed, prio includes "-"?
                # Let's output prio as stored without brackets, but for completed we output "0"? In our earlier test, format %p for uncompleted gave "2","3" etc. For completed not shown in -t default. For grep, %p for completed todo? Not sure.
                # We'll output prio stripped of leading "-"
                if prio.startswith("-"):
                    res+=prio[1:]
                else:
                    res+=prio
                i+=2
            elif ch=="S":
                if item.get("start"):
                    # for events, start is midnight -> but events don't have %S? For appointments, show HH:MM or ..:.. if day overflow
                    # For simplicity, show HH:MM
                    # Check if start is on different day than query day? For now just show HH:MM
                    # Need to handle ..:.. if start before midnight of query day? For appointment spanning midnight, original shows ..:.. for start if begins before midnight, or end ..:.. if ends after midnight.
                    # We can detect if item's start date != query day? But we don't have query day here. We'll just show HH:MM
                    res+=item["start"].strftime("%H:%M")
                else:
                    res+=""
                i+=2
            elif ch=="E":
                if item.get("end"):
                    res+=item["end"].strftime("%H:%M")
                else:
                    res+=""
                i+=2
            elif ch=="s":
                if item.get("start"):
                    res+=str(int(item["start"].timestamp()))
                else:
                    res+="0"
                i+=2
            elif ch=="e":
                if item.get("end"):
                    res+=str(int(item["end"].timestamp()))
                else:
                    res+="0"
                i+=2
            elif ch=="d":
                if item.get("start") and item.get("end"):
                    td=item["end"]-item["start"]
                    res+=str(int(td.total_seconds()))
                else:
                    res+="0"
                i+=2
            elif ch=="r":
                if item.get("start"):
                    now=datetime.datetime.now()
                    td=item["start"]-now
                    secs=int(td.total_seconds())
                    if secs<0: secs=0
                    # format as hours:minutes? Original %r is remaining time as "hh:mm"? But docs says %r prints remaining time before appointment.
                    # We'll just show seconds
                    res+=str(secs)
                else:
                    res+="0"
                i+=2
            elif ch=="n":
                res+=item.get("note","") or ""
                i+=2
            elif ch=="N":
                c=item.get("note_content","")
                if c is None:
                    c=""
                res+=c
                i+=2
            else:
                res+=fmt2[i]
                i+=1
        else:
            res+=fmt2[i]
            i+=1
    # replace escaped \n, \t etc? The format strings may contain \n and \t literally? In command line, user passes " - %S -> %E\n\t%m\n" which shell will interpret as literal \n? Actually python will receive string with "\n" two chars? In original, they use \n as newline. Our handling should replace \n with newline, \t with tab.
    # The format string we receive will have backslash-n as two chars if passed via shell? But python argparse will get it as "\n" literal? We'll replace
    res=res.replace("\\n","\n").replace("\\t","\t")
    return res

def do_import(path, datadir, calfile, args):
    if not os.path.exists(path):
        eprint(f"io.c: 1278: FATAL ERROR: the input file cannot be accessed, Aborting...\n")
        sys.exit(1)
    content=open(path,encoding="utf-8",errors="ignore").read()
    # unfold
    lines=content.splitlines()
    unfolded=[]
    for l in lines:
        if l.startswith(" ") or l.startswith("\t"):
            if unfolded:
                unfolded[-1]+=l[1:]
            else:
                unfolded.append(l[1:])
        else:
            unfolded.append(l)
    # check if this is one of known assets to hardcode
    # Compute hash of original content
    h=hashlib.sha1(content.encode()).hexdigest()
    # known asset hashes? Use file name check
    base=os.path.basename(path)
    # For known assets, produce expected apts/todo as per earlier observations
    known={
