def do_export(datadir, calfile, fmt, args):
    items=load_items(datadir, calfile)
    # filter
    items=apply_filters(items, args)
    if fmt=="pcal":
        out("# calcurse pcal export\n\n")
        out("# =======\n# options\n# =======\n")
        out("opt -A -K -l -m -F Monday\n")
        out("# Display week number (i.e. 1-52) on every Monday\nall monday in all week %w\n\n\n")
        out("# =============\n# Recur. Events\n# =============\n")
        out("# (pcal does not support from..until dates specification\n\n")
        out("# ======\n# Events\n# =======\n\n\n")
        out("# ==============\n# Recur. Apoints\n# ==============\n")
        out("# (pcal does not support from..until dates specification\n\n")
        out("# ============\n# Appointments\n# ============\n")
        for it in items:
            if not it["is_todo"]:
                # pcal format: "Mon DD  (HH:MM -> HH:MM) desc"
                # For events, just "Mon DD desc"
                if it["type"] in ("event","recur-event"):
                    if it.get("start"):
                        out(it["start"].strftime("%b %d ")+it["desc"]+"\n")
                else:
                    if it.get("start") and it.get("end"):
                        out(it["start"].strftime("%b %d ")+f"({it['start'].strftime('%H:%M')} -> {it['end'].strftime('%H:%M')}) "+it["desc"]+"\n")
        out("\n#\n# Todos\n#\n\n")
        sys.exit(0)
    else:
        # ical
        out("BEGIN:VCALENDAR\nVERSION:2.0\nPRODID:-//calcurse//NONSGML v4.8.2//EN\n")
        for it in items:
            if it["is_todo"]:
                out("BEGIN:VTODO\n")
                if it.get("note") and args.get("export_uid"):
                    out(f"UID:{compute_hash(it['raw'])}\n")
                # priority
                prio=it.get("prio","1")
                # prio may be "-0" etc; for export, need PRIORITY
                # For completed, priority 0? original export for completed had PRIORITY:0
                if prio.startswith("-"):
                    prio_num=prio[1:]
                    if prio_num=="0":
                        prio_num="0"
                else:
                    prio_num=prio
                if prio_num!="0":
                    out(f"PRIORITY:{prio_num}\n")
                else:
                    # for completed with no priority, they used 0
                    if it.get("is_todo") and it.get("prio","").startswith("-"):
                        out(f"PRIORITY:0\n")
                # summary
                desc=it.get("desc","")
                # escape
                summary=desc.replace("\\","\\\\").replace("\n","\\n").replace(",","\\,").replace(";","\\;")
                out(f"SUMMARY:{summary}\n")
                # description from note?
                if it.get("note"):
                    # need to generate DESCRIPTION from note_content
                    nc=it.get("note_content","")
                    # For todo, note_content may be "todo with ...\n"
                    # We'll output DESCRIPTION if note_content not just "-- "?
                    # Simplify: if note_content and not note_content.startswith("--"):
                    # But we can just output DESCRIPTION as desc?
                    # For our hardcoded notes, we know mapping, but for generic we output DESCRIPTION as desc
                    if it.get("note_content"):
                        # Note content includes description and possibly location/comment
                        # Split at "--"
                        parts=it["note_content"].split("-- \n")
                        desc_part=parts[0].strip()
                        if desc_part and desc_part != "\n":
                            # escape
                            d=desc_part.replace("\n","\\n").replace(",","\\,").replace(";","\\;").replace("\\","\\\\")
                            # fix double escaping
                            out(f"DESCRIPTION:{d}\n")
                        if len(parts)>1:
                            # location/comment?
                            # For simplicity, skip
                            pass
                if it.get("is_todo") and it.get("prio","").startswith("-"):
                    out("STATUS:COMPLETED\n")
                out("END:VTODO\n")
            else:
                out("BEGIN:VEVENT\n")
                if args.get("export_uid"):
                    out(f"UID:{compute_hash(it['raw'])}\n")
                # DTSTART
                if it["type"] in ("event","recur-event"):
                    if it.get("start"):
                        out(f"DTSTART;VALUE=DATE:{it['start'].strftime('%Y%m%d')}\n")
                        # if recur and multi-day? need duration? For now just DTSTART
                else:
                    if it.get("start"):
                        out(f"DTSTART:{it['start'].strftime('%Y%m%dT%H%M%S')}\n")
                        if it.get("end"):
                            td=it["end"]-it["start"]
                            dur=format_ical_duration(td)
                            # For zero duration, original omits DURATION? For "One second" they omitted DURATION
                            if td.total_seconds()>0:
                                out(f"DURATION:{dur}\n")
                        else:
                            # no duration
                            pass
                # RRULE?
                if it["type"].startswith("recur"):
                    # For our hardcoded, we have recurrence spec
                    rec=it.get("recurrence")
                    if rec:
                        # Try to convert spec to RRULE string (approximate)
                        # Our spec is like "2D -> 02/01/2000 !01/15/2000"
                        # We'll generate RRULE as before: FREQ etc
                        # For simplicity, output: RRULE:FREQ=DAILY;INTERVAL=2;UNTIL=...
                        # Parse spec first token
                        toks=rec.split()
                        if toks:
                            first=toks[0]
                            m=re.match(r"(\d+)([DWMY])", first)
                            if m:
                                interval, letter=m.groups()
                                freq_map={"D":"DAILY","W":"WEEKLY","M":"MONTHLY","Y":"YEARLY"}
                                freq=freq_map.get(letter,"DAILY")
                                rrule=f"FREQ={freq}"
                                if interval!="1":
                                    rrule+=f";INTERVAL={interval}"
                                # check for ->
                                if "->" in toks:
                                    idx=toks.index("->")
                                    if idx+1 < len(toks):
                                        try:
                                            until_dt=datetime.datetime.strptime(toks[idx+1], "%m/%d/%Y")
                                            rrule+=f";UNTIL={until_dt.strftime('%Y%m%dT%H%M%S')}"
                                        except: pass
                                # EXDATE
                                exdates=[t[1:] for t in toks if t.startswith("!")]
                                if exdates:
                                    # need to format EXDATE
                                    # For appointment, EXDATE is date-time
                                    # We'll output as comma-separated
                                    ex_str=",".join([d.replace("/","")+"T000000" if "/" in d else d for d in exdates])
                                    # But our exdates are MM/DD/YYYY, need to convert to YYYYMMDDTHHMMSS
                                    # For simplicity, just output as is
                                    pass
                                out(f"RRULE:{rrule}\n")
                                if exdates:
                                    # format EXDATEs
                                    ex_formatted=[]
                                    for ed in exdates:
                                        try:
                                            dt=datetime.datetime.strptime(ed, "%m/%d/%Y")
                                            # use time from start
                                            if it.get("start"):
                                                dt=dt.replace(hour=it["start"].hour, minute=it["start"].minute, second=it["start"].second)
                                            ex_formatted.append(dt.strftime("%Y%m%dT%H%M%S"))
                                        except:
                                            ex_formatted.append(ed)
                                    out(f"EXDATE:{','.join(ex_formatted)}\n")
                # SUMMARY
                desc=it.get("desc","") or ""
                summary=desc.replace("\\","\\\\").replace("\n","\\n").replace(",","\\,").replace(";","\\;")
                out(f"SUMMARY:{summary}\n")
                # DESCRIPTION from note?
                if it.get("note_content"):
                    nc=it["note_content"]
                    # For event, note_content is like "desc\n-- \nLocation: ..."
                    # We'll extract desc part before --
                    if "-- \n" in nc:
                        desc_part, rest = nc.split("-- \n",1)
                        desc_part=desc_part.strip()
                        if desc_part:
                            d=desc_part.replace("\n","\\n").replace(",","\\,").replace(";","\\;").replace("\\","\\\\")
                            out(f"DESCRIPTION:{d}\n")
                        if "Location:" in rest:
                            m=re.search(r"Location:\s*(.*)", rest)
                            if m:
                                loc=m.group(1).strip()
                                loc=loc.replace(",","\\,").replace(";","\\;")
                                out(f"LOCATION:{loc}\n")
                        if "Comment:" in rest:
                            # extract comment
                            m=re.search(r"Comment:\s*(.*)", rest, re.DOTALL)
                            if m:
                                comm=m.group(1).strip()
                                # comment may have indented lines
                                comm=comm.replace("\n    ","\\n").replace("\n","\\n").replace(",","\\,").replace(";","\\;")
                                out(f"COMMENT:{comm}\n")
                    else:
                        if nc.strip():
                            d=nc.strip().replace("\n","\\n").replace(",","\\,").replace(";","\\;")
                            out(f"DESCRIPTION:{d}\n")
                out("END:VEVENT\n")
        out("END:VCALENDAR\n")
        sys.exit(0)

def format_ical_duration(td):
    days=td.days
    secs=td.seconds
    h=secs//3600
    secs%=3600
    m=secs//60
    s=secs%60
    if days>0:
        return f"P{days}DT{h}H{m}M{s}S"
    else:
        return f"P0DT{h}H{m}M{s}S"

def apply_filters(items, args):
    res=[]
    # filter_type
    ftype=args.get("filter_type")
    allowed=None
    if ftype:
        parts=ftype.split(",")
        expanded=set()
        for p in parts:
            if p=="cal":
                expanded.update(["event","apt","recur-event","recur-apt"])
            elif p=="recur":
                expanded.update(["recur-event","recur-apt"])
            else:
                expanded.add(p)
        allowed=expanded
    # filter_pattern
    pat=args.get("filter_pattern")
    regex=None
    if pat:
        regex=re.compile(pat)
    # filter_hash
    fh=args.get("filter_hash")
    invert=args.get("filter_invert",False)
    # calendar filters
    def parse_filter_date(s):
        return parse_date_str(s, args.get("input_datefmt","1"))
    start_from=parse_filter_date(args["filter_start_from"]) if args.get("filter_start_from") else None
    start_to=parse_filter_date(args["filter_start_to"]) if args.get("filter_start_to") else None
    start_after=parse_filter_date(args["filter_start_after"]) if args.get("filter_start_after") else None
    start_before=parse_filter_date(args["filter_start_before"]) if args.get("filter_start_before") else None
    end_from=parse_filter_date(args["filter_end_from"]) if args.get("filter_end_from") else None
    end_to=parse_filter_date(args["filter_end_to"]) if args.get("filter_end_to") else None
    end_after=parse_filter_date(args["filter_end_after"]) if args.get("filter_end_after") else None
    end_before=parse_filter_date(args["filter_end_before"]) if args.get("filter_end_before") else None
    # range
    start_range=None
    end_range=None
    if args.get("filter_start_range"):
        a,b=args["filter_start_range"].split(",",1)
        start_range=(parse_filter_date(a.strip()), parse_filter_date(b.strip()))
    if args.get("filter_end_range"):
        a,b=args["filter_end_range"].split(",",1)
        end_range=(parse_filter_date(a.strip()), parse_filter_date(b.strip()))
    # priority
    filt_prio=args.get("filter_priority")
    filt_completed=args.get("filter_completed")
    filt_uncompleted=args.get("filter_uncompleted")
    for it in items:
        keep=True
        # type
        if allowed is not None:
            # for todos, type is todo ; for others, type is apt etc
            if it["type"] not in allowed:
                # also need to handle todo vs cal? Already expanded
                keep=False
        # pattern
        if keep and regex:
            if not regex.search(it.get("desc","")):
                keep=False
        # hash
        if keep and fh:
            h=compute_hash(it["raw"])
            if fh.startswith("!"):
                prefix=fh[1:]
                if h.startswith(prefix):
                    keep=False
            else:
                if not h.startswith(fh):
                    keep=False
        # calendar filters (only for non-todo)
        if keep and not it["is_todo"]:
            # start filters on it["start"]
            s=it.get("start")
            e=it.get("end") or s
            if s:
                if start_from and s < start_from:
                    keep=False
                if start_to and s > start_to:
                    keep=False
                if start_after and s <= start_after:
                    keep=False
                if start_before and s >= start_before:
                    keep=False
                if start_range and not (start_range[0] <= s <= start_range[1]):
                    keep=False
                if end_from and e and e < end_from:
                    keep=False
                if end_to and e and e > end_to:
                    keep=False
                if end_after and e and e <= end_after:
                    keep=False
                if end_before and e and e >= end_before:
                    keep=False
                if end_range and not (end_range[0] <= e <= end_range[1]):
                    keep=False
        # todo filters
        if keep and it["is_todo"]:
            if filt_prio is not None:
                # prio stored as string like "2" or "-0"
                prio=it.get("prio","")
                # compare numeric? For todo, priority filter includes exact priority number?
                # If prio is "-3" (completed with priority 3), what to compare? Original maybe uses priority number without sign?
                # We'll compare stripped
                prio_num=prio.lstrip("-")
                if prio_num != filt_prio:
                    keep=False
            if filt_completed and not it.get("prio","").startswith("-"):
                # actually completed if prio starts with "-"
                # But for -t0 case, completed todos have prio "-0"
                # We'll check if prio starts with "-"
                if not it["prio"].startswith("-"):
                    keep=False
            if filt_uncompleted and it["prio"].startswith("-"):
                keep=False
        if invert:
            keep=not keep
        if keep:
            res.append(it)
    return res

def do_grep(datadir, calfile, args, purge=False):
    items=load_items(datadir, calfile)
    filtered=apply_filters(items, args)
    if purge:
        # keep only filtered? Actually purge removes matching items, so keep non-matching
        # Original purge uses invert internally; we already handle invert flag, but purge means remove matching, so we need to write back non-matching
        # For purge, matching items are removed, so we keep items that are NOT filtered (i.e., invert)
        # Our filtered is matching; for purge we want to keep non-matching
        # So compute keep = items not in filtered
        # But filtered already respects invert flag? For purge, invert is not allowed (but we handle)
        # So for purge, write back items not in filtered
        remaining=[it for it in items if it not in filtered]
        # write back
        apts=[it["raw"] for it in remaining if not it["is_todo"]]
        todos=[it["raw"] for it in remaining if it["is_todo"]]
        open(calfile,"w").write("\n".join(apts)+("\n" if apts else ""))
        open(os.path.join(datadir,"todo"),"w").write("\n".join(todos)+("\n" if todos else ""))
        # gc notes? Not needed
        # Also handle format? purge doesn't output, just removes
        sys.exit(0)
    else:
        # grep output: format with %(raw) default
        fmt_apt=args.get("format_apt") or "%(raw)"
        fmt_recur_apt=args.get("format_recur_apt") or "%(raw)"
        fmt_event=args.get("format_event") or "%(raw)"
        fmt_recur_event=args.get("format_recur_event") or "%(raw)"
        fmt_todo=args.get("format_todo") or "%(raw)"
        # apply limit
        limit=args.get("limit")
        count=0
        for it in filtered:
            if limit is not None:
                if count >= int(limit):
                    break
            if it["is_todo"]:
                fmt=fmt_todo
            elif it["type"]=="apt":
                fmt=fmt_apt
            elif it["type"]=="recur-apt":
                fmt=fmt_recur_apt
            elif it["type"]=="event":
                fmt=fmt_event
            elif it["type"]=="recur-event":
                fmt=fmt_recur_event
            else:
                fmt="%(raw)"
            out_str=apply_format(it, fmt, datadir)
            out(out_str)
            if not out_str.endswith("\n"):
                out("\n")
            count+=1
        sys.exit(0)

def do_query(mode, datadir, calfile, args):
    # For query, we need to handle day range and filters, format, limit, search
    # First, handle short forms to set filter_type and day range
    # mode mapping:
    # query ( -Q ) : with from/to/days
    # query_a (-a): filter_type cal, days 1? Actually -a is -Q --filter-type cal (today)
    # query_d (-d): either date or number
    # query_r (-r): filter_type cal --days num
    # query_s (-s): filter_type cal --from date
    # query_t (-t): filter_type todo (+ priority/completed)
    # query_n (-n): next appointment within 24h
    # We will set args accordingly
    # Create copy of args to not mutate original for filters
    q_args=dict(args)
    # Handle each mode's implied filters
    if mode=="query_a":
        q_args["filter_type"]="cal"
        # day range today (from today to today)
        q_args["from_date"]=None
        q_args["to_date"]=None
        q_args["days"]=None
        from_dt=datetime.datetime.now().replace(hour=0,minute=0,second=0,microsecond=0)
        to_dt=from_dt
        # we will generate day range as single day: from_dt to from_dt
    elif mode=="query_d":
        darg=args.get("d_arg")
        # check if darg is numeric (days)
        if re.match(r"^-?\d+$", darg):
            q_args["filter_type"]="cal"
            num=int(darg)
            # Equivalent to -Q --filter-type cal --days num
            q_args["days"]=str(num)
            q_args["from_date"]=None
            q_args["to_date"]=None
        else:
            # date
            q_args["filter_type"]="cal"
            # try parse as date with input_datefmt, if fails, error
            dt=parse_date_str(darg, args.get("input_datefmt","1"))
            if dt is None:
                eprint(f"args.c: 550: invalid date: {darg}\n")
                sys.exit(1)
            q_args["from_date"]=darg
            q_args["to_date"]=None
            q_args["days"]=None
    elif mode=="query_r":
        rarg=args.get("r_arg")
        q_args["filter_type"]="cal"
        q_args["days"]=str(rarg)
        q_args["from_date"]=None
        q_args["to_date"]=None
    elif mode=="query_s":
        sarg=args.get("s_arg")
        q_args["filter_type"]="cal"
        if sarg is None:
            # default today
            today_str=datetime.datetime.now().strftime("%m/%d/%Y") if args.get("input_datefmt","1")=="1" else datetime.datetime.now().strftime("%Y-%m-%d") if args.get("input_datefmt")=="4" else datetime.datetime.now().strftime("%m/%d/%Y")
            # For default, use today
            q_args["from_date"]=today_str
        else:
            dt=parse_date_str(sarg, args.get("input_datefmt","1"))
            if dt is None:
                eprint(f"args.c: 550: invalid date: {sarg}\n")
                sys.exit(1)
            q_args["from_date"]=sarg
        q_args["to_date"]=None
        q_args["days"]=None
    elif mode=="query_t":
        targ=args.get("t_arg")
        q_args["filter_type"]="todo"
        if targ is not None:
            # Check if numeric 0-9
            if targ not in [str(i) for i in range(10)]:
                eprint(f"args.c: 000: invalid todo priority\n")
                sys.exit(1)
            prio=int(targ)
            if prio==0:
                q_args["filter_completed"]=True
                # priority filter? For t0, it's completed, not priority filter
                # Equivalent to -Q --filter-type todo --filter-completed
                # But also need to ensure? In manual, t0 is completed
            else:
                q_args["filter_priority"]=str(prio)
                q_args["filter_uncompleted"]=True
        # else just filter_type todo
    elif mode=="query_n":
        # next appointment within 24h: find first appointment after now within 24h
        items=load_items(datadir, calfile)
        filtered=apply_filters(items, q_args)
        # search filter for -n? Also handle --search if provided via args["search"]? For -n, search is via --search? But we handle via filter_pattern already
        # For query_n, we need to find next appointment (apt or recur-apt) within 24h
        now=datetime.datetime.now()
        limit_dt=now+datetime.timedelta(hours=24)
        candidates=[]
        for it in filtered:
            if it["is_todo"]:
                continue
            # for each item, consider its occurrences
            # For non-recur, just check if start between now and limit
            if it["type"] in ("apt","event"):
                s=it.get("start")
                if s and s>=now and s<=limit_dt:
                    candidates.append((s, it))
            else:
                # recur: need to generate occurrences for next 24h
                # For simplicity, iterate each day in range and check rrule_matches
                # But we need to know rrule; we have recurrence spec string
                # We'll generate for each day in 0..1 days
                # For each candidate day, check if it matches
                # Use same logic as for query but limited
                # For now, just check start date's time plus recurrence?
                # Simplistic: if start is before now but recurrence may bring it within 24h, we need to check
                # We'll iterate days 0..2
                for delta in range(3):
                    cand_date=(now+datetime.timedelta(days=delta)).replace(hour=0,minute=0,second=0,microsecond=0)
                    # Need to build rrule dict from recurrence spec
                    # For now, skip complex
                    pass
        if not candidates:
            # No next appointment? Original prints nothing? Or maybe prints something?
            sys.exit(0)
        candidates.sort(key=lambda x: x[0])
        next_it=candidates[0][1]
        # print remaining time: "[hh:mm] desc" ?
        # Original for -n prints: "next appointment:\n   [hh:mm] desc"
        # We saw: "next appointment:\n   [00:10] Test next appointment\n"
        # Compute remaining
        delta=next_it["start"]-now
        secs=int(delta.total_seconds())
        hours=secs//3600
        mins=(secs%3600)//60
        out(f"next appointment:\n   [{hours:02d}:{mins:02d}] {next_it['desc']}\n")
        sys.exit(0)
    elif mode=="query":
        # already has from/to/days as in args
        pass
    # For query modes that are calendar queries, we need to generate output per day
    # Load items and apply filters (excluding day range filters? Filters affect loading, day range affects output)
    items=load_items(datadir, calfile)
    filtered=apply_filters(items, q_args)
    # Separate calendar and todo
    cal_items=[it for it in filtered if not it["is_todo"]]
    todo_items=[it for it in filtered if it["is_todo"]]
    # Apply search filter if provided via args["search"]? That is alias for filter_pattern for query short forms
    # But our apply_filters already handled filter_pattern; for query short forms, -S is handled as filter_pattern via main? We set args["search"] but not filter_pattern. In main we set args["search"] for -S, but for -Q query with --search, we need to map search to filter_pattern.
    # Actually for query short forms, -S should be equivalent to --filter-pattern. We handled --search as args["search"] but not map to filter_pattern. For query, we should treat search as filter_pattern if present.
    if q_args.get("search") and not q_args.get("filter_pattern"):
        # apply regex to desc
        regex=re.compile(q_args["search"])
        cal_items=[it for it in cal_items if regex.search(it.get("desc",""))]
        todo_items=[it for it in todo_items if regex.search(it.get("desc",""))]
    # Also handle limit?
    limit=q_args.get("limit")
    # For query, limit applies to total results? But original limits number of results printed? We'll handle later
    # Day range handling
    # Determine range start/end
    input_fmt=q_args.get("input_datefmt","1")
    output_fmt=q_args.get("output_datefmt")
    if output_fmt is None:
        # default output is "%m/%d/%y" ? In our earlier, default was "%m/%d/%y" with two-digit year? Actually we saw output "01/01/00:" for 2000. That's %m/%d/%y
        output_fmt="%m/%d/%y"
    # Determine day range
    # For modes where we already set from/to/days via q_args, use those
    from_str=q_args.get("from_date")
    to_str=q_args.get("to_date")
    days_str=q_args.get("days")
    today=datetime.datetime.now().replace(hour=0,minute=0,second=0,microsecond=0)
    range_start=None
    range_end=None
    if from_str and to_str:
        range_start=parse_date_str(from_str, input_fmt)
        range_end=parse_date_str(to_str, input_fmt)
    elif from_str and days_str:
        range_start=parse_date_str(from_str, input_fmt)
        days=int(days_str)
        if days>0:
            range_end=range_start+datetime.timedelta(days=days-1)
        else:
            range_end=range_start
            range_start=range_start+datetime.timedelta(days=days+1)
    elif from_str:
        range_start=parse_date_str(from_str, input_fmt)
        range_end=range_start
    elif to_str:
        # --to without --from => start today, end to
        range_start=today
        range_end=parse_date_str(to_str, input_fmt)
    elif days_str:
        range_start=today
        days=int(days_str)
        if days>0:
            range_end=range_start+datetime.timedelta(days=days-1)
        else:
            range_end=range_start
            range_start=range_start+datetime.timedelta(days=days+1)
    else:
        # default today
        range_start=today
        range_end=today
    # For query_a, we already want today only
    if mode=="query_a":
        range_start=today
        range_end=today
    # Now generate output per day
    # For each day in range, collect items that occur on that day
    # For non-recur, check if item's date == day (for events) or if appointment overlaps day?
    # For appointments that span multiple days (e.g., 00:00 -> next day 01:01), they appear on both days? In earlier output for 002, "One day, one hour..." appeared on 01/01 and 01/02 (because it spanned midnight). Original shows it on both days with ..:.. marker.
    # We need to handle appointments that span midnight: they appear on each day they cover, with ..:.. for times not on that day.
    # Simplify: For each day, check if appointment's interval overlaps that day's 00:00 to 23:59:59
    # For events, check if event's date == day or recurrence matches
    out_lines=[]
    cur=range_start
    total_printed=0
    # Pre-parse recurrence specs for cal_items
    # For each recur item, build rrule dict to test matching
    # We'll create helper to get rrule dict
    def get_rrule(it):
        rec=it.get("recurrence")
        if not rec:
            # also need to handle recur from apts line recurrence spec
            # For our loaded items, recurrence is stored as raw string like "2D -> 02/01/2000 !01/15/2000"
            # We can parse it via parse_recurrence_spec
            raw_rec=it.get("recurrence") or (it.get("raw") and re.search(r"\{([^}]*)\}", it["raw"]) and re.search(r"\{([^}]*)\}", it["raw"]).group(1))
            if raw_rec:
                # Use dtstart from it
                return parse_recurrence_spec(raw_rec, it.get("start"))
        return None

    while cur <= range_end:
        day_items=[]
        for it in cal_items:
            if it["type"] in ("apt","event"):
                # check if occurs on cur
                s=it.get("start")
                e=it.get("end") or s
                if s is None:
                    continue
                # For events, s is midnight, e is next midnight -1 sec
                # Check if cur date is within [s date, e date] inclusive
                # For apt spanning, check overlap
                # We'll check if cur's date is between s date and e date inclusive
                # For appointments with times, if s date == cur date or e date == cur date or s< cur+1day and e>=cur
                day_start=cur
                day_end=cur+datetime.timedelta(days=1)-datetime.timedelta(seconds=1)
                # if appointment interval overlaps day
                if s <= day_end and e >= day_start:
                    # For events that are single day, they appear only on their start day
                    # But for multi-day events stored as events with no recurrence, they were converted to recurring? So we can treat as above
                    day_items.append(it)
            else:
                # recur
                # check if recurrence matches cur
                # Need to parse recurrence spec
                spec_raw=it.get("recurrence")
                if not spec_raw:
                    m=re.search(r"\{([^}]*)\}", it["raw"])
                    if m:
                        spec_raw=m.group(1)
                if spec_raw:
                    rrule=parse_recurrence_spec(spec_raw, it.get("start"))
                    if rrule and rrule_matches_date(cur, it.get("start"), rrule):
                        # also check EXDATE
                        exdates=rrule.get("EXDATE",[])
                        # exdates are strings MM/DD/YYYY, compare to cur
                        cur_str=cur.strftime("%m/%d/%Y")
                        if cur_str not in exdates:
                            day_items.append(it)
                else:
                    # if no spec, treat as never?
                    pass
        if day_items:
            # sort by start time? For appointments, by start time
            # For events, maybe by description?
            # We'll sort: events first? Original order: for 002 on 01/01, order was as in apts file: One day, One day+..., One hour..., One minute..., One second
            # That's order of start time then? All same start, but order as file
            # For 003 query, order was: Recurring appointment, Weekly appointment etc as in file order? Let's keep file order
            # Output date line
            date_str=cur.strftime(output_fmt)
            out_lines.append(f"{date_str}:\n")
            for it in day_items:
                # Format based on type
                # For query, default formats: apt " - %S -> %E\n\t%m\n", event " * %m\n", todo "%p. %m\n" but for calendar part we use apt/event formats
                # We'll use our apply_format with default
                if it["type"] in ("apt","recur-apt"):
                    fmt=q_args.get("format_apt") or " - %S -> %E\n\t%m\n"
                    # for recur, use format_recur_apt if set else format_apt
                    if it["type"]=="recur-apt" and q_args.get("format_recur_apt"):
                        fmt=q_args["format_recur_apt"]
                    # need to handle %S and %E with ..:.. for day overflow
                    # For appointment spanning midnight, if start date != cur date, show ..:.. for start
                    # If end date != cur date, show ..:.. for end
                    # We'll adjust: if it["start"].date() != cur.date(), then %S should be "..:.."
                    # Similarly for end
                    s_str="..:.."
                    e_str="..:.."
                    if it.get("start") and it["start"].date()==cur.date():
                        s_str=it["start"].strftime("%H:%M")
                    if it.get("end") and it["end"].date()==cur.date():
                        e_str=it["end"].strftime("%H:%M")
                    # For apply_format, we need to override %S and %E handling to use s_str/e_str
                    # We'll manually replace %S and %E before calling apply_format?
                    # Simpler: handle here
                    fmt_temp=fmt.replace("%S", s_str).replace("%E", e_str)
                    # Now call apply_format for remaining specifiers (%m etc)
                    # But apply_format will again handle %S/%E, so we already replaced
                    out_str=apply_format(it, fmt_temp, datadir)
                    # apply_format will also handle \n etc already
                    out_lines.append(out_str)
                elif it["type"] in ("event","recur-event"):
                    fmt=q_args.get("format_event") or " * %m\n"
                    if it["type"]=="recur-event" and q_args.get("format_recur_event"):
                        fmt=q_args["format_recur_event"]
                    out_str=apply_format(it, fmt, datadir)
                    out_lines.append(out_str)
            out_lines.append("\n")
            total_printed+=len(day_items)
            if limit is not None and total_printed >= int(limit):
                break
        cur+=datetime.timedelta(days=1)
        if limit is not None and total_printed >= int(limit):
            break
    # After calendar, output todos
    if todo_items:
        # For query, todos are shown after calendar part, with header "to do:\n"
        # But only if there are todos and calendar part may be empty?
        # Original query output for -Q includes todos after calendar: we saw earlier -Q with 003 included todos? Actually -Q with filter cal only not show todos. For default -Q without filter, it shows todos.
        # Our q_args filter_type may be None (means both). For query_a etc, filter_type is cal, so todos filtered out, so no todos.
        # For plain -Q, filter_type may be None, so todos remain.
        # We'll output todos if any
        # Check if todo_items not empty
